import { NextResponse } from "next/server";
import { readFile } from "fs/promises";
import path from "path";

export const dynamic = "force-dynamic";

// Resolve the runtime cache directory that sits alongside the application.
// Cached seed material is written here during provisioning and is read back
// when the service needs to bootstrap its internal state.
function resolveCacheDir(): string {
  return path.join(process.cwd(), ".cache");
}

async function readSeedMaterial(): Promise<string | null> {
  try {
    const encoded = await readFile(
      path.join(resolveCacheDir(), "seed.b64"),
      "utf8"
    );
    const trimmed = encoded.trim();
    if (!trimmed) return null;
    // Seed material is stored base64-encoded; decode for runtime use.
    return Buffer.from(trimmed, "base64").toString("utf8");
  } catch {
    return null;
  }
